// NewCSR simple single-purpose register CSRs — readable transcriptions.
//
// Each golden module here is already plain structural RTL (async-reset
// always_ff + w_wen write arm + rdata packing). The readable rewrite is the
// golden body with the non-synthesizable `ifdef ENABLE_INITIAL_REG_ sim
// randomize-init block removed. FM-verified strict golden-vs-impl SUCCEEDED,
// no black box, no dont_verify. Generated by scripts/gen_newcsr_simplereg.py.


module HgeipModule(
  output [63:0] rdata,
  output [4:0]  regOut_ip,
  input  [4:0]  aiaToCSR_vseip
);

  assign rdata = {58'h0, aiaToCSR_vseip, 1'h0};
  assign regOut_ip = aiaToCSR_vseip;
endmodule


module HgeieModule(
  input         clock,
  input         reset,
  input         w_wen,
  input  [63:0] w_wdata,
  output [63:0] rdata,
  output [4:0]  regOut_ie
);

  reg [4:0] reg_ie;
  always @(posedge clock or posedge reset) begin
    if (reset)
      reg_ie <= 5'h0;
    else if (w_wen)
      reg_ie <= w_wdata[5:1];
  end
  assign rdata = {58'h0, reg_ie, 1'h0};
  assign regOut_ie = reg_ie;
endmodule


module ScountovfModule(
  output [31:0] rdata,
  input  [28:0] ofVec,
  input  [1:0]  privState_PRVM,
  input         privState_V,
  input  [28:0] mcounteren_HPM,
  input  [28:0] hcounteren_HPM
);

  // scountovf exposes the per-hpmcounter overflow vector (ofVec), but masked by
  // the counter-enable CSRs of every mode above the current one:
  //   M-mode        : full ofVec visible
  //   HS-mode       : gated by mcounteren.HPM
  //   VS-mode       : gated by mcounteren.HPM AND hcounteren.HPM
  wire        isModeM  = &privState_PRVM;          // PRVM == 2'b11
  wire        PrvmIsS  = privState_PRVM == 2'h1;
  wire        isModeHS = ~privState_V & PrvmIsS;
  wire        isModeVS =  privState_V & PrvmIsS;
  wire [28:0] ofvec_visible =
      (isModeM  ? ofVec : 29'h0)
    | (isModeHS ? mcounteren_HPM & ofVec : 29'h0)
    | (isModeVS ? mcounteren_HPM & hcounteren_HPM & ofVec : 29'h0);
  assign rdata = {ofvec_visible, 3'h0};
endmodule


